using System;using System.IO;using System.Speech.Synthesis;using System.Speech.AudioFormat;using System.Web.Script.Serialization;
class CreateTavernDemoAudio{static void Main(){string dir="D:/WORK/Cet6Story/assets/tavern/listening";var groups=new JavaScriptSerializer().Deserialize<TavernListeningGroup[]>(File.ReadAllText(Path.Combine(dir,"groups.json")));using(var voice=new SpeechSynthesizer()){bool found=false;foreach(var v in voice.GetInstalledVoices())if(v.Enabled&&v.VoiceInfo.Culture.TwoLetterISOLanguageName=="en"){voice.SelectVoice(v.VoiceInfo.Name);found=true;Console.WriteLine("Voice: "+v.VoiceInfo.Name);break;}if(!found)throw new Exception("English voice required");voice.Rate=-1;voice.Volume=90;foreach(var group in groups){voice.SetOutputToWaveFile(Path.Combine(dir,group.audio),new SpeechAudioFormatInfo(24000,AudioBitsPerSample.Sixteen,AudioChannel.Mono));voice.Speak(group.transcript);voice.SetOutputToNull();Console.WriteLine(group.audio);}}}}
